package com.tekwatt.support.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="support_ticket_comments")public class TicketComment{@Id private UUID id;@Column(nullable=false)private UUID ticketId;private UUID authorId;@Column(nullable=false,length=120)private String authorName;@Column(nullable=false,columnDefinition="TEXT")private String body;@Column(nullable=false)private boolean internalNote;@Column(nullable=false,updatable=false)private Instant createdAt;protected TicketComment(){}public TicketComment(UUID t,UUID a,String n,String b,boolean i){id=UUID.randomUUID();ticketId=t;authorId=a;authorName=n;body=b;internalNote=i;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getTicketId(){return ticketId;}public UUID getAuthorId(){return authorId;}public String getAuthorName(){return authorName;}public String getBody(){return body;}public boolean isInternalNote(){return internalNote;}public Instant getCreatedAt(){return createdAt;}}
